import{z as s,x as n,o as l,c as A,q as p,j as B,D as E,d as t,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"采样温度与探索","description":"","frontmatter":{"title":"采样温度与探索","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rl-sampling-temperature.md","filePath":"llm/rl-sampling-temperature.md","lastUpdated":1791413859000}'),u={name:"llm/rl-sampling-temperature.md"};function d(m,a,h,D,g,_){const r=n("Mermaid");return l(),A("div",null,[a[2]||(a[2]=p('<h1 id="采样温度与探索" tabindex="-1">采样温度与探索 <a class="header-anchor" href="#采样温度与探索" aria-label="Permalink to &quot;采样温度与探索&quot;">​</a></h1><div class="epigraph"><p>训练期温度是环境动力学的一部分：它改的是 π_beh，不是后处理装饰。</p><footer>—— 对照 DAPO 评测温度 1.0；R1 / GRPO 用组采样吃温度带来的多样；解码课里的温度对推理另文</footer></div><p><a href="/llm/rollout-weight-sync">上一课</a>保证权重一致。生成还要选温度、top-\\(p\\)。缺口是：<strong>这些解码超参改变 rollout 分布，等于改环境；训练与评测不一致，曲线对不上。</strong> 本课写 RL 训练期的温度。熵正则鼓励局部随机；温度是采样时对 logits 的全局缩放，两者相关不等价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>策略网络输出的是 \\(\\pi_\\theta(\\cdot\\mid s)\\)。温度为 \\(\\tau\\) 的采样来自 \\(\\pi_\\theta^{1/\\tau}\\) 再归一化（对 logits 除 \\(\\tau\\)）。\\(\\tau\\gt 1\\) 展平分布，组内更易分叉，<a href="/llm/grpo">GRPO</a> 更有相对信号；\\(\\tau\\lt 1\\) 接近 greedy，组内复制，动态采样狂丢组。DAPO 评测 AIME 用温度 1.0、top-\\(p=0.7\\)。许多助手服务默认 \\(\\tau=0.7\\)。用服务温度做训练，探索不足；用训练温度做产品，用户看见胡言。</p><p><span class="marginnote">数字实例：logits 为 \\([4,2]\\) 时，\\(\\tau=1\\) 的概率约 \\([0.88,0.12]\\)；\\(\\tau=2\\) 变 \\([2,1]\\)，概率约 \\([0.73,0.27]\\)；\\(\\tau=0.5\\) 变 \\([8,4]\\)，概率约 \\([0.98,0.02]\\) 接近 greedy。温度就是对同一张 logits 表做整体缩放。</span></p><p>top-\\(p\\) / top-\\(k\\) 把支撑截断，IS 的 \\(\\pi_\\theta\\) 若在全词表上算，与真正 \\(\\pi_{\\mathrm{beh}}\\) 不一致。要么训练前向也施加同一截断，要么训练期关掉核采样，只留温度。</p><h3 id="温度不是熵系数" tabindex="-1">温度不是熵系数 <a class="header-anchor" href="#温度不是熵系数" aria-label="Permalink to &quot;温度不是熵系数&quot;">​</a></h3><p>\\(\\alpha H\\) 在训练目标里推高熵；\\(\\tau\\) 在数据收集时改变样本。只加 \\(\\alpha\\) 而 \\(\\tau\\to 0\\)，仍采不到高熵区域。只升温而 clip 对称，罕见 token 仍抬不起来。探索预算要三处一起声明：\\(\\tau\\)、clip、\\(\\alpha\\)。</p><p><span class="marginnote">术语翻译：熵系数 \\(\\alpha H\\) 是写进损失里的「鼓励分心条款」，训的是参数；温度 \\(\\tau\\) 是采样时拧的「分心旋钮」，改的是这一步抽哪个 token。两个通道独立，只拧一个、另一个拧死，探索照样不到位——所以要 \\(\\tau\\)、clip、\\(\\alpha\\) 一起声明。</span></p><p><span class="marginnote">评测 pass@\\(k\\) 依赖温度。报 avg@32 必须写 \\(\\tau\\)。与训练 \\(\\tau\\) 不同时，那是另一项实验。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练默认 \\(\\tau=1\\)，使采样分布等于网络定义的 \\(\\pi\\)，IS 干净。需要更多分叉时升到 \\(1.1\\)–\\(1.3\\) 并盯语言崩坏。核采样：训练期优先关；若开，logprob 按核内重新归一化存储。评测协议单独成表。课程式：前期 \\(\\tau\\) 高找策略，后期降 \\(\\tau\\) 榨贪婪准确率——必须在金标上验证，否则只是过拟合训练采样器。</p>',13)),(l(),B(i,null,{default:E(()=>[o(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20TAU%5B%22%E6%B8%A9%E5%BA%A6%20%CF%84%22%5D%20--%3E%20BEH%5B%22%CF%80_beh%20%E5%8F%98%E5%B9%B3%E6%88%96%E5%8F%98%E5%B0%96%22%5D%0A%20%20BEH%20--%3E%20G%5B%22%E7%BB%84%E5%86%85%E5%A4%9A%E6%A0%B7%22%5D%0A%20%20G%20--%3E%20ADV%5B%22GRPO%20%E7%9B%B8%E5%AF%B9%E4%BC%98%E5%8A%BF%22%5D%0A%20%20TOP%5B%22top-p%20%E6%88%AA%E6%94%AF%E6%92%91%22%5D%20--%3E%20IS%5B%22%E4%B8%8E%E5%85%A8%E8%AF%8D%E8%A1%A8%20%CF%80_%CE%B8%20%E4%B8%8D%E4%B8%80%E8%87%B4%22%5D%0A%20%20IS%20--%3E%20FIX%5B%22%E8%AE%AD%E7%BB%83%E5%85%B3%E6%A0%B8%E9%87%87%E6%A0%B7%E6%88%96%E6%8C%89%E6%A0%B8%E9%87%8D%E5%BD%92%E4%B8%80%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[t("与 "),e("a",{href:"/llm/kl-free-rl"},"无 KL"),t(" 叠加时，高 \\(\\tau\\) 没有参考拉回，更易胡言，靠过长过滤与重复检测托底。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"\\(\\tau\\) 改变的是动作分布的温度，不改变奖励。高 \\(\\tau\\) 提高碰到对的链的机会，也提高格式破坏。可验证抽取失败率随 \\(\\tau\\) 上升，是预期，不是 bug。应先 SFT 锁格式，再升温。这与可验证奖励课的「先低温度巩固抽取」一致，本课把它接到 GRPO 组方差。",-1)),(l(),B(i,null,{default:E(()=>[o(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20UP%5B%22%E5%8D%87%E6%B8%A9%EF%BC%9A%CF%84%20%E9%AB%98%E4%BA%8E%201%22%5D%20--%3E%20OPP%5B%22%E6%9B%B4%E6%98%93%E7%A2%B0%E5%88%B0%E5%AF%B9%E7%9A%84%E9%93%BE%22%5D%0A%20%20UP%20--%3E%20RISK%5B%22%E6%A0%BC%E5%BC%8F%E7%A0%B4%E5%9D%8F%20%2F%20%E6%8A%BD%E5%8F%96%E5%A4%B1%E8%B4%A5%E7%8E%87%E5%8D%87%22%5D%0A%20%20OPP%20--%3E%20SIG%5B%22%E7%BB%84%E6%96%B9%E5%B7%AE%E5%A4%A7%EF%BC%9AGRPO%20%E6%9C%89%E7%9B%B8%E5%AF%B9%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20RISK%20--%3E%20MIT%5B%22%E5%85%88%20SFT%20%E9%94%81%E6%A0%BC%E5%BC%8F%EF%BC%8C%E8%BF%87%E6%BB%A4%E5%85%9C%E5%BA%95%22%5D%0A%20%20DOWN%5B%22%E9%99%8D%E6%B8%A9%EF%BC%9A%CF%84%20%E4%BD%8E%E4%BA%8E%201%22%5D%20--%3E%20GREEDY%5B%22%E7%BB%84%E5%86%85%E5%A4%8D%E5%88%B6%EF%BC%9A%E5%85%A8%E5%AF%B9%E6%88%96%E5%85%A8%E9%94%99%22%5D%0A%20%20GREEDY%20--%3E%20NOSIG%5B%22std%20%3D%200%EF%BC%9A%E5%8A%A8%E6%80%81%E9%87%87%E6%A0%B7%E4%B8%A2%E7%BB%84%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=p('<p><span class="marginnote">常见误区：初学者容易以为训练温度越高学得越多。高 \\(\\tau\\) 多出来的样本大半是被过滤器丢掉的格式坏链——信号没有变多，算力白烧。升温要盯的是「有效组数」与抽取失败率，不是「采了多少」。</span></p><p><span class="marginnote">同一 \\(\\tau\\)，长链后期熵本就低（模型很确定下一个词）。全程固定 \\(\\tau\\) 不等于全程同等探索。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>产品若必须低 \\(\\tau\\)，训练后期应有一段匹配产品解码的微调，否则 train-serve gap。那与后课精度不匹配是两类 gap：一类是解码，一类是数值。难度课程（下一课）会调节题，不调节 \\(\\tau\\)；两者都在控制「有效探索」，不要同时盲扫。评测 pass@\\(k\\) 与训练 \\(\\tau\\) 必须写在同一张实验卡上。</p><p>训练默认 τ=1 使采样分布等于网络 π；核采样若开，存储的 logπ 必须按核重归一，否则 IS 从第一枚 token 就偏。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>训练温度定义 \\(\\pi_{\\mathrm{beh}}\\)；默认 1.0 与网络 \\(\\pi\\) 一致。</li><li>核采样截支撑会破坏 IS，训练期宜关。</li><li>\\(\\tau\\)、clip、熵项共同组成探索预算，不能只拧一个。</li><li>评测温度必须写入协议；与服务温度对齐是单独阶段。</li><li>出处：Yu 等 DAPO 评测设置；Shao 等 GRPO 组采样；Ouyang 等对解码与训练一致性的工程要求。</li></ul>',7))])}const P=s(u,[["render",d]]);export{c as __pageData,P as default};
